def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    from datetime import time, timezone, timedelta

    if nanoseconds is None:
        raise ValueError("nanoseconds must not be None")
    if not isinstance(nanoseconds, int):
        try:
            nanoseconds = int(nanoseconds)
        except Exception:
            raise TypeError("nanoseconds must be an integer")
    if nanoseconds < 0:
        raise ValueError("nanoseconds must be non-negative")

    # Normalize to a single day
    nanoseconds %= 86400 * 1_000_000_000

    total_seconds = nanoseconds // 1_000_000_000
    remainder_nano = nanoseconds % 1_000_000_000
    microsecond = remainder_nano // 1_000

    hour = (total_seconds // 3600) % 24
    minute = (total_seconds % 3600) // 60
    second = total_seconds % 60

    tzinfo = None
    if tz is not None:
        if isinstance(tz, timezone):
            tzinfo = tz
        elif isinstance(tz, str):
            s = tz.strip()
            if s in ('Z', '+00:00', '-00:00'):
                tzinfo = timezone.utc
            else:
                sign = 1
                if s.startswith('+'):
                    s = s[1:]
                elif s.startswith('-'):
                    sign = -1
                    s = s[1:]
                try:
                    hours_str, minutes_str = s.split(':')
                    hours = int(hours_str)
                    minutes = int(minutes_str)
                    offset = timedelta(hours=hours, minutes=minutes) * sign
                    tzinfo = timezone(offset)
                except Exception:
                    raise ValueError(f"Invalid timezone format: {tz}")
        else:
            raise TypeError("tz must be a string or datetime.timezone object")

    return time(hour, minute, second, microsecond, tzinfo=tzinfo)

