def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return: A serialisable representation of the time, or None if ``value`` is ``None``.
    """
    if value is None:
        return None

    # Handle native datetime.time objects or any object providing ``strftime``.
    try:
        if hasattr(value, "strftime"):
            # Format as ISO-like HH:MM:SS (with optional fractional seconds if present).
            fmt = "%H:%M:%S"
            # If microseconds are non‑zero, include them.
            try:
                if getattr(value, "microsecond", 0):
                    fmt += "%f"
            except Exception:
                pass
            return value.strftime(fmt).rstrip("0").rstrip(".")
    except Exception:
        # Any error falls through to the generic conversion below.
        pass

    # Try converting via a ``value`` attribute (common pattern for custom classes).
    try:
        if hasattr(value, "value"):
            return str(value.value)
    except Exception:
        pass

    # Fallback to the default string representation.
    return str(value)

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    # Return early for None
    if value is None:
        return None

    # If it's already a datetime.time instance, use isoformat
    try:
        import datetime
    except ImportError:
        raise RuntimeError("datetime module is required for dehydrating time values")

    if isinstance(value, datetime.time):
        return value.isoformat()

    # Try to construct a datetime.time from attributes of the value
    try:
        hour = getattr(value, "hour")
        minute = getattr(value, "minute")
        second = getattr(value, "second")
        microsecond = getattr(value, "microsecond", 0)
        tzinfo = getattr(value, "tzinfo", None)

        # Create a new datetime.time object to canonicalise
        t = datetime.time(hour, minute, second, microsecond, tzinfo)
        return t.isoformat()
    except Exception as exc:
        raise ValueError(f"Cannot dehydrate value {value!r} as a time: {exc}") from exc

