    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    # Handle None values gracefully
    if value is None:
        return None

    # If the value already has an isoformat method (e.g., datetime.time), use it
    if hasattr(value, "isoformat"):
        try:
            return value.isoformat()
        except Exception as exc:
            raise ValueError(f"Unable to dehydrate time value: {exc}") from exc

    # If the value is a simple tuple of (hour, minute, second, microsecond)
    if (isinstance(value, tuple) and 1 <= len(value) <= 4 and
