        try:
            return f"{hour:02d}:{minute:02d}:{second:02d}.{microsecond:06d}".rstrip("0").rstrip(".")
        except Exception as exc:
            raise ValueError(f"Invalid time tuple: {exc}") from exc

    # Fallback: try str conversion
    try:
        return str(value)
    except Exception as exc:
        raise TypeError(f"Unsupported type for dehydration: {type(value)!r}") from exc

