def dehydrate_point(value):
    """Dehydrator for Point data.

    :param value: The point to dehydrate.
    :type value: Point
    :return: A simple serialisable representation of the point.  For a
             typical point this will be a dictionary with ``x`` and ``y``
             keys, and, if present, a ``z`` key.  ``None`` is returned
             unchanged.  If *value* is a tuple or list it will be
             converted to an equivalent dictionary.  If the point object
             provides a ``to_dict`` or ``to_tuple`` method those will be
             used.  Raises ``TypeError`` if the object cannot be de‑hydrated.
    """
    # Return None unchanged
    if value is None:
        return None

    # If the value already provides a serialisable representation
    if hasattr(value, "to_dict") and callable(value.to_dict):
        return value.to_dict()
    if hasattr(value, "to_tuple") and callable(value.to_tuple):
        tup = value.to_tuple()
        if isinstance(tup, (tuple, list)):
            # Convert tuple/list to dict form
            if len(tup) == 2:
                return {"x": tup[0], "y": tup[1]}
            if len(tup) == 3:
                return {"x": tup[0], "y": tup[1], "z": tup[2]}

    # Accept plain tuple/list representations
    if isinstance(value, (tuple, list)):
        if len(value) == 2:
            return {"x": value[0], "y": value[1]}
        if len(value) == 3:
            return {"x": value[0], "y": value[1], "z": value[2]}
        raise ValueError(
            f"Tuple or list representation must have 2 (x,y) or 3 (x,y,z) elements, got {len(value)}"
        )

    # Attempt to read x, y, (optional z) attributes
    try:
        x = getattr(value, "x")
        y = getattr(value, "y")
    except AttributeError as exc:
        raise TypeError(f"Object of type {type(value).__name__} "
                        f"does not have required 'x' and 'y' attributes") from exc

    result = {"x": x, "y": y}
    # Optional z
    z = getattr(value, "z", None)
    if z is not None:
        result["z"] = z
    return result

