def unit_of_work(metadata=None, timeout=None):
    """
    Decorator factory that applies optional metadata and timeout to a transaction.

    :param metadata: A dictionary of metadata to be attached to the transaction.
                     It will be set by calling `CALL dbms.setTXMetaData($meta)` inside
                     the transaction. If the procedure is not available the call is
                     ignored.
    :param timeout:  The transaction timeout in seconds.  If `None` no timeout
                     is set.  If zero the default database timeout is used.
                     Negative values raise :class:`ValueError`.  The timeout
                     is applied with `CALL dbms.setTransactionTimeout($timeout)`.

    The decorated function must accept a single ``tx`` argument which
    represents the Neo4j transaction.
    """
    def decorator(func):
        def inner(tx):
            if metadata is not None:
                try:
                    tx.run("CALL dbms.setTXMetaData($meta)", {"meta": metadata})
                except Exception:
                    # Ignore failure if the procedure is unavailable
                    pass
            if timeout is not None:
                if not isinstance(timeout, (int, float)):
                    raise TypeError("timeout must be a number or None")
                if timeout < 0:
                    raise ValueError("timeout must not be negative")
                if timeout != 0:
                    try:
                        tx.run("CALL dbms.setTransactionTimeout($timeout)", {"timeout": timeout})
                    except Exception:
                        # Ignore failure if the procedure is unavailable
                        pass
            return func(tx)
        return inner
    return decorator

