def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os
    import shlex
    import sys

    if not cmd:
        return cmd

    first = cmd[0]
    # Only React on windows
    if not sys.platform.startswith("win"):
        return cmd

    # If the first element is a file that exists, try to read its shebang
    if not os.path.isfile(first):
        return cmd

    try:
        with open(first, "rb") as f:
            firstline = f.readline()
    except Exception:
        return cmd

    # Shebang lines start with "!#"
    if not firstline.startswith(b"#!"):
        return cmd

    # Parse shebang
    try:
        shebang = firstline[2:].decode(errors="ignore").strip()
    except Exception:
        return cmd

    parts = shlex.split(shebang)
    if not parts:
        return cmd

    interpreter = parts[0]
    args_of_interpreter = parts[1:]

    # Handle env
    if os.path.basename(interpreter).lower() in ("env", "env.exe") and args_of_interpreter:
        interpreter = args_of_interpreter[0]
        args_of_interpreter = args_of_interpreter[1:]

    # If the interpreter is a path relative to the shebang file, resolve it
    try:
        if not os.path.isabs(interpreter):
            base_dir = os.path.dirname(first)
            interpreter_path = os.path.normpath(os.path.join(base_dir, interpreter))
            if os.path.exists(interpreter_path):
                interpreter = interpreter_path
    except Exception:
        pass

    # Quote if necessary
    def _quote(s: str) -> str:
        if " " in s or "\t" in s or "'" in s or '"' in s:
            return f'"{s}"'
        return s

    new_cmd = [interpreter] + args_of_interpreter + list(cmd[1:])

    return tuple(new_cmd)

