@classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        tb_module = __import__('traceback')
        try:
            tb = getattr(e, "__traceback__", None)
            if tb is None:
                return str(e)
            frames = tb_module.extract_tb(tb)
            parts = ["Traceback (most recent call last):"]
            for i, frm in enumerate(frames[:max_level]):
                filename = frm.filename
                try:
                    os = __import__('os')
                    parts_file = filename.split(os.sep)
                    if len(parts_file) > max_path_level:
                        filename = os.sep.join(parts_file[-max_path_level:])
                except Exception:
                    # Fallback: keep original filename
                    pass
                parts.append(f'  File "{filename}", line {frm.lineno}, in {frm.name}')
                if frm.line:
                    parts.append(f'    {frm.line.strip()}')
            parts.append(f'{type(e).__name__}: {e}')
            return "\n".join(parts)
        except Exception:
            return str(e)

