def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Ensure we are working with an iterable
    try:
        iterable = list(classes)
    except TypeError:
        raise TypeError("Input must be an iterable of class objects")

    # Preserve order while removing duplicates
    seen = set()
    unique = []
    for cls in iterable:
        if cls not in seen:
            seen.add(cls)
            unique.append(cls)

    # Keep only classes that are not superclasses of any other class in the list
    minimal = []
    for cls in unique:
        is_super = False
        for other in unique:
            if other is cls:
                continue
            try:
                if issubclass(other, cls):
                    is_super = True
                    break
            except TypeError:
                # Skip non-class items if present
                continue
        if not is_super:
            minimal.append(cls)

    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Validate input: all elements should be types (classes)
    for c in classes:
        if not isinstance(c, type):
            raise TypeError(f"Expected class type, got {type(c)}")
    result = []
    for c in classes:
        # Skip if already covered by an existing base
        if any(issubclass(c, b) for b in result):
            continue
        # Remove any bases that are subclasses of the new base
        result = [b for b in result if not issubclass(b, c)]
        result.append(c)
    return result

