    minimal = []
    for c in iterable:
        if not isinstance(c, type):
            raise TypeError(f"Item {c!r} is not a class object")

        skip = False
        new_minimal = []
        for s in minimal:
            try:
                if issubclass(c, s):
                    # s is an ancestor of c → drop s
                    continue
                if issubclass(s, c):
                    # s is a subclass of c → c is redundant
                    skip = True
                    break
            except TypeError:
                # In case of non-related types that cannot be compared
                new_minimal.append(s)
        if not skip:
            new_minimal.append(c)
        minimal = new_minimal
    return minimal

