def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface.

    If ``all`` is True, returns all public attributes, with description if available,
    otherwise ``None``.  If ``all`` is False, returns only attributes that have a
    non-empty description.

    Returns:
        dict[str, str or None]: Mapping of attribute name to its description.
