    result = {}
    try:
        # Get all public attributes of the instance (ignore special/private and methods)
        for name in dir(self):
            if name.startswith('_'):
                continue
            try:
                value = getattr(self, name)
            except Exception:
                # Skip attributes that raise errors on access
                continue
            if callable(value):
                continue

            description = None
            # First try to get description from the class descriptor (common pattern)
            cls_attr = getattr(self.__class__, name, None)
            for attr_name in ('description', 'desc', 'doc'):
                if hasattr(cls_attr, attr_name):
                    description = getattr(cls_attr, attr_name)
                    break
            # Fallback: try to get description from the instance attribute itself
            if description is None and hasattr(value, 'description'):
                description = getattr(value, 'description')

            if all or description:
                result[name] = description
    except Exception:
        # In case of unforeseen errors, return what we have gathered so far
        pass
    return result

