def to_csv(self, separator=",", header=None):
        """Convert graph's points to CSV.

        *separator* delimits values, the default is comma.

        *header*, if not ``None``, is the first string of the output
        (new line is added automatically).

        Since a graph can be multidimensional,
        for each point first its coordinate is converted to string
        (separated by *separator*), then each part of its value.

        The method returns the CSV string.
        """
        lines = []

        # Optional header
        if header is not None:
            lines.append(str(header))

        # Helper to decide if a value is iterable but not a string/bytes
        def is_iterable(val):
            try:
                iter(val)
                return not isinstance(val, (str, bytes))
            except TypeError:
                return False

        # The graph points are expected to be an iterable of (coords, value) tuples.
        points = getattr(self, "points", None)
        if points is None:
            # No points attribute, raise a clear error
            raise AttributeError("Graph object does not have a 'points' attribute")

        for point in points:
            try:
                coords, value = point
            except Exception:
                # Skip malformed points
                continue

            # Convert coordinates
            try:
                coords_str = separator.join(map(str, coords))
            except TypeError:
                # If coords is not iterable, treat it as a single value
                coords_str = str(coords)

            # Convert value
            if is_iterable(value):
                try:
                    value_str = separator.join(map(str, value))
                except Exception:
                    # Fallback to string representation if conversion fails
                    value_str = str(value)
            else:
                value_str = str(value)

            # Combine into a line
            line = coords_str + separator + value_str
            lines.append(line)

        return "\n".join(lines)

