    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Collect lines, optionally with header
    lines = []
    if header is not None:
        lines.append(str(header))

    # Iterate over points in the graph
    points = getattr(self, "points", None)
    if points is None:
        return "\n".join(lines)

    for point in points:
        try:
            # Extract coordinates; point may expose them via .coordinates or __iter__
            if hasattr(point, "coordinates"):
                coords = point.coordinates
            elif hasattr(point, "__iter__") and not isinstance(point, str):
                coords = list(point)
            else:
                coords = [point]
        except Exception:
            # Skip points that cannot provide coordinates
            continue

        # Convert coordinates to strings
        coord_strs = []
        for c in coords:
            try:
                coord_strs.append(str(c))
            except Exception:
                coord_strs.append("")

        # Get value parts (possibly multi‑valued)
        values = []
        try:
            val = getattr(point, "value", None)
            if val is None:
                val = getattr(point, "values", None)
            if val is None:
                val = getattr(point, "data", None)
        except Exception:
            val = None

        if isinstance(val, (list, tuple, set)) and not isinstance(val, str):
            values = [str(v) for v in val]
        else:
            values = [str(val)] if val is not None else []

        # Build the CSV line
