def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    try:
        bins_list = list(bins)
        edges_list = list(edges)
    except TypeError as exc:
        raise TypeError(f"bins and edges must be iterable, got {exc}") from exc

    if not bins_list:
        return 0.0

    if len(edges_list) != len(bins_list) + 1:
        raise ValueError("Length of edges must be one more than length of bins")

    # check edges are numeric and sorted
    try:
        edges_sorted = [float(e) for e in edges_list]
    except (TypeError, ValueError) as exc:
        raise TypeError(f"All edge values must be numeric, got invalid entry: {exc}") from exc

    if any(a > b for a, b in zip(edges_sorted, edges_sorted[1:])):
        raise ValueError("Edges must be in ascending order")

    # compute widths
    widths = [b - a for a, b in zip(edges_sorted, edges_sorted[1:])]

    # compute area
    total = 0.0
    for bin_val, width in zip(bins_list, widths):
        try:
            val = float(bin_val)
        except (TypeError, ValueError) as exc:
            raise TypeError(f"All bin values must be numeric, got invalid entry: {exc}") from exc
        total += val * width

    return total

