    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Validate inputs
    if bins is None or edges is None:
        raise TypeError("Both 'bins' and 'edges' must be provided")

    try:
        bins = list(bins)
        edges = list(edges)
    except TypeError:
        raise TypeError("'bins' and 'edges' must be iterable")

    if len(edges) != len(bins) + 1:
        raise ValueError(
            "Number of edges must be one more than the number of bins"
        )

    total = 0.0
    for bin_val, left_edge, right_edge in zip(bins, edges, edges[1:]):
        try:
            width = right_edge - left_edge
        except TypeError:
            raise TypeError("Edge values must support subtraction")
        try:
            contribution = bin_val * width
        except TypeError:
            raise TypeError("Bin values must support multiplication with a width")
        total += contribution

    return total

