def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package

    Returns
    -------
    dict
    """
    import os

    if not isinstance(folder, str):
        raise TypeError("folder must be a string path")
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Folder not found: {folder}")

    grouped = {}
    try:
        for entry in os.listdir(folder):
            path = os.path.join(folder, entry)
            if not os.path.isfile(path):
                continue
            base, _ = os.path.splitext(entry)
            if base not in grouped:
                grouped[base] = []
            grouped[base].append(entry)
    except OSError as exc:
        raise RuntimeError(f"Error reading directory {folder}") from exc

    # Keep only groups that have at least one XML file
    result = {}
    for base, files in grouped.items():
        if any(f.lower().endswith(".xml") for f in files):
            result[base] = [os.path.join(folder, f) for f in sorted(files)]

    return result

