def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    # Validate the hook argument
    if not isinstance(hook, HookType):
        raise TypeError(f"hook must be an instance of HookType, got {type(hook).__name__}")

    # Ensure the registry entry for this hook exists
    if not hasattr(self, 'registry'):
        self.registry = {}
    if hook not in self.registry:
        self.registry[hook] = []

    def decorator(func):
        # Ensure the object being decorated is callable
        if not callable(func):
            raise TypeError(f"decorated object must be callable, got {type(func).__name__}")

        try:
            self.registry[hook].append(func)
        except Exception as exc:  # pragma: no cover
            raise RuntimeError(f"Failed to register handler for hook {hook}: {exc}") from exc

        return func

    return decorator

