def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess, os, shlex

    # Validate input
    if commands is None:
        raise ValueError("No command specified")

    # Convert command input to list
    if isinstance(commands, str):
        # Split shell-style quoting
        commands_list = shlex.split(commands)
    elif isinstance(commands, (list, tuple)):
        commands_list = list(commands)
    else:
        raise TypeError(f"commands must be str, list, or tuple; got {type(commands).__name__}")

    # Ensure args is iterable of strings
    if args is None:
        args_list = []
    else:
        if isinstance(args, (str, bytes)):
            # treat single string as single argument
            args_list = [args]
        elif isinstance(args, (list, tuple)):
            args_list = list(args)
        else:
            raise TypeError(f"args must be str, list, or tuple; got {type(args).__name__}")

    # Merge environment
    merged_env = os.environ.copy()
    if env:
        if not isinstance(env, dict):
            raise TypeError(f"env must be a dict; got {type(env).__name__}")
        merged_env.update({k: str(v) for k, v in env.items()})

    # Prepare stderr handling
    stderr_target = subprocess.DEVNULL if hide_stderr else None

    # Build full command
    full_cmd = commands_list + args_list

    if verbose:
        print(f"Running command: {' '.join(shlex.quote(arg) for arg in full_cmd)}")
        if cwd:
            print(f"Working directory: {cwd}")

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=merged_env,
            stdout=subprocess.PIPE,
            stderr=stderr_target,
            text=True,
            check=True
        )
        return result
    except subprocess.CalledProcessError as e:
        # Return the CompletedProcess even on error if needed
        # Optionally include stderr in output if not hidden
        errmsg = f"Command '{' '.join(full_cmd)}' returned non-zero exit status {e.returncode}."
        if not hide_stderr:
            errmsg += f"\nStderr: {e.stderr}"
        raise RuntimeError(errmsg) from e
    except OSError as e:
        raise RuntimeError(f"Failed to start command '{' '.join(full_cmd)}': {e}") from e

