def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, (str, bytes)):
        raise TypeError(f"vcs must be a string, not {type(vcs).__name__}")
    if not callable(method):
        raise TypeError(f"method must be callable, not {type(method).__name__}")

    # Retrieve or create the global registry dictionary
    registry = globals().get("VCS_HANDLERS")
    if registry is None:
        registry = {}
        globals()["VCS_HANDLERS"] = registry
    if not isinstance(registry, dict):
        raise RuntimeError("VCS_HANDLERS is not a dictionary")

