    if vcs in registry:
        raise RuntimeError(f"A handler for VCS '{vcs}' is already registered")

    # Register the method
    registry[vcs] = method

    # Optional: attach metadata to the function
    try:
        setattr(method, "__vcs_handler__", vcs)
    except Exception:
        # If setting attribute fails (e.g. built-in functions), ignore
        pass

    return method

def register_vcs_handler(vcs, method):
