    global _VCS_HANDLERS
    if '_VCS_HANDLERS' not in globals():
        _VCS_HANDLERS = {}

    if not isinstance(vcs, str):
        raise TypeError(f"vcs name must be a string, got {type(vcs).__name__}")

    # If the second argument is callable, register it immediately
    if callable(method):
        if vcs in _VCS_HANDLERS and _VCS_HANDLERS[vcs] is not method:
            raise ValueError(f"A handler for VCS '{vcs}' is already registered")
        _VCS_HANDLERS[vcs] = method
        return method

    # Otherwise, assume it's a decorator factory; return a decorator
    def decorator(func):
        if not callable(func):
            raise TypeError("decorated object must be callable")
        if vcs in _VCS_HANDLERS:
            raise ValueError(f"A handler for VCS '{vcs}' is already registered")
        _VCS_HANDLERS[vcs] = func
        return func

    return decorator

def register_vcs_handler(vcs, method=None):
    """Create decorator to mark a method as the handler of a VCS."""
    if method is None:
        # been called with only the VCS name, return a decorator
        def decorator(func):
            if not callable(func):
                raise TypeError(f"Expected a callable to decorate, got {type(func).__name__}")
            if not isinstance(vcs, str):
                raise TypeError(f"VCS identifier must be a string, got {type(vcs).__name__}")
            # Attach the VCS identifier to the function for introspection
            setattr(func, "_vcs_handler", vcs)
            # Keep a simple registry on the decorator function
            registry = getattr(register_vcs_handler, "_registry", {})
            if vcs in registry:
                # Warn the user that an existing handler is being overridden
                # but don't raise to keep it simple.
                pass
            registry[vcs] = func
            setattr(register_vcs_handler, "_registry", registry)
            return func
        return decorator
    else:
        # The function was supplied directly; decorate it immediately
        return register_vcs_handler(vcs)(method)

