def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    def _validate_element(elem):
        nonlocal num_objects, good_objects
        num_objects += 1
        is_valid = True

        # Validate the element itself if requested
        if validate_objects and hasattr(elem, "validate"):
            try:
                result = elem.validate()
                if isinstance(result, bool):
                    is_valid = result
                else:
                    # If validate returns None or other, consider it valid
                    is_valid = True
            except Exception as exc:
                if show_warnings:
                    print(f"Warning: Validation of element {elem} failed with error: {exc}")
                is_valid = False

        # Check digests if requested
        if check_digests and hasattr(elem, "verify_digest"):
            try:
                digest_ok = elem.verify_digest()
                if not digest_ok:
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Digest check failed for element {elem}")
            except Exception as exc:
                if show_warnings:
                    print(f"Warning: Digest verification of element {elem} raised exception: {exc}")
                is_valid = False

        if is_valid:
            good_objects += 1

        # Recursively validate children if the element is iterable
        try:
            iterator = iter(elem)
        except TypeError:
            return
        for child in iterator:
            _validate_element(child)

    _validate_element(self)
    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0

        def _check(obj):
            nonlocal num_objects, good_objects
            num_objects += 1
            ok = True

            # Validate the object itself if requested
            if validate_objects:
                try:
                    if hasattr(obj, "validate") and callable(obj.validate):
                        result = obj.validate()
                        if result is False:
                            ok = False
                            if show_warnings:
                                print(f"[WARN] Validation failed for {obj}")
                    # If no validate method, assume it's valid
                except Exception as exc:
                    ok = False
                    if show_warnings:
                        print(f"[WARN] Validation error in {obj}: {exc}")

            # Check digests if requested
            if check_digests:
                try:
                    if hasattr(obj, "digest") and hasattr(obj, "compute_digest"):
                        expected = getattr(obj, "digest")
                        actual = obj.compute_digest()
                        if expected != actual:
                            ok = False
                            if show_warnings:
                                print(f"[WARN] Digest mismatch in {obj}: expected {expected}, got {actual}")
                except Exception as exc:
                    ok = False
                    if show_warnings:
                        print(f"[WARN] Digest check error in {obj}: {exc}")

            if ok:
                good_objects += 1

            # Recurse into children if iterable
            try:
                for child in obj:
                    _check(child)
            except TypeError:
                # Not iterable
                pass

        _check(self)
        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    warnings = []

    def _traverse(comp):
        nonlocal num_objects, good_objects
        try:
            num_objects += 1

            ok = True

            if validate_objects:
                if hasattr(comp, 'validate'):
                    try:
                        if not comp.validate():
                            ok = False
                            warnings.append((comp, "validate() returned False"))
                    except Exception as e:
                        ok = False
                        warnings.append((comp, f"validate() raised exception: {e}"))
                else:
