                    warnings.append((comp, "no validate() method"))

            if check_digests and ok:
                if hasattr(comp, 'check_digest'):
                    try:
                        if not comp.check_digest():
                            ok = False
                            warnings.append((comp, "check_digest() returned False"))
                    except Exception as e:
                        ok = False
                        warnings.append((comp, f"check_digest() raised exception: {e}"))
                else:
                    ok = False
                    warnings.append((comp, "no check_digest() method"))

            if ok:
                good_objects += 1

        except Exception as exc:
            warnings.append((None, f"Unhandled exception during traversal: {exc}"))

        # Recurse into children if the component is iterable
        try:
            for child in comp:
                _traverse(child)
        except TypeError:
            # Not iterable, nothing to recurse into
            pass

    try:
        _traverse(self)
    except Exception as main_exc:
        if show_warnings:
            print(f"Fatal error during hierarchy validation: {main_exc}")
        return 0, 0

    if show_warnings and warnings:
        for obj, msg in warnings:
            identifier = f"id={obj.id}" if obj and hasattr(obj, "id") else ""
