def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """

        # Helper to perform the validation on a single element
        def _validate_elem(elem):
            is_good = True
            # Object validation
            if validate_objects and hasattr(elem, 'validate'):
                try:
                    if not elem.validate():
                        is_good = False
                except Exception as exc:
                    is_good = False
                    if show_warnings:
                        try:
                            elem_repr = getattr(elem, '__repr__', lambda: str(elem))()
                        except Exception:
                            elem_repr = str(elem)
                        print(f"Warning: validation failed for {elem_repr} with error: {exc}")
            # Digest checking
            if check_digests and hasattr(elem, 'digest'):
                try:
                    expected = None
                    # Try to compute digest if method exists
                    if hasattr(elem, 'compute_digest'):
                        expected = elem.compute_digest()
                    # If not, fall back to get_digest if available
                    elif hasattr(elem, 'get_digest'):
                        expected = elem.get_digest()
                    # If we have neither, skip check
                    if expected is not None and expected != elem.digest:
                        is_good = False
                        if show_warnings:
                            try:
                                elem_repr = getattr(elem, '__repr__', lambda: str(elem))()
                            except Exception:
                                elem_repr = str(elem)
                            print(f"Warning: digest mismatch for {elem_repr}")
                except Exception as exc:
                    is_good = False
                    if show_warnings:
                        try:
                            elem_repr = getattr(elem, '__repr__', lambda: str(elem))()
                        except Exception:
                            elem_repr = str(elem)
                        print(f"Warning: digest check failed for {elem_repr} with error: {exc}")
            return is_good

        num_objects = 0
        good_objects = 0

        # Breadth-first traversal to avoid recursion depth issues
        stack = [self]
        while stack:
            node = stack.pop()
            num_objects += 1
            if _validate_elem(node):
                good_objects += 1
            # Add children to stack if the node is iterable
            try:
                # Skip if node is a primitive or has no children
                iterator = iter(node)
            except TypeError:
                continue
            else:
                # For each child, add to stack
                for child in iterator:
                    # Only process object-like children, skip primitives
                    if hasattr(child, '__iter__') or callable(child):
                        stack.append(child)
                    else:
                        # Primitive values are counted but not further traversed
                        try:
                            if _validate_elem(child):
                                good_objects += 0  # they were already counted
                        except Exception:
                            pass
        return num_objects, good_objects

