def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os
    from pathlib import Path

    # Resolve the target root path
    try:
        root_path = Path(self.root_path).resolve()
    except Exception as exc:
        raise ValueError(f"Invalid root_path '{self.root_path}': {exc}") from exc

    # If the root already exists, we don't want to overwrite it
    if root_path.exists():
        raise FileExistsError(f"OCFL root already exists at {root_path!s}")

    # Create the root directory structure
    try:
        root_path.mkdir(parents=True, exist_ok=False)
    except Exception as exc:
        raise RuntimeError(f"Failed to create OCFL root directory '{root_path}': {exc}") from exc

    # Create a minimal .ocflconfig file
    config_file = root_path / ".ocflconfig"
    config_contents = "root_version = 1.0\n"
    try:
        config_file.write_text(config_contents, encoding="utf-8")
    except Exception as exc:
        # Clean up the created directory if configuration writing fails
        try:
            root_path.rmdir()
        except Exception:
            pass
        raise RuntimeError(f"Failed to write .ocflconfig at '{config_file}': {exc}") from exc

    # Store the root path on the instance for future use
    try:
        self.root = root_path
    except Exception:
        # Ignore if the attribute does not exist; not critical
        pass

    return root_path

