            namaste_matches = list(p.glob('0=*'))
            if namaste_matches:
                # Any namaste file hints this is an object directory
                return 'object'

            # If no namaste file here, check if children contain one -> root
            for child in p.iterdir():
                if child.is_dir():
                    if list(child.glob('0=*')):
                        return 'root'

            # Not an OCFL root or object
            return f"unrecognised directory format at {path}"

        # Might be other types (device, symlink, etc.)
        return f"unknown type at {path}"
    except Exception as e:
        return f"error determining path type: {e}"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    try:
        if not os.path.exists(path):
            return "error: path does not exist"

        if os.path.isfile(path):
            return "file"

        if os.path.isdir(path):
            # Search for a Namaste file that starts with "0="
            try:
                entries = os.listdir(path)
            except OSError as exc:
                return f"error: cannot list directory '{path}': {exc}"

            namaste_file = next((f for f in entries if f.startswith("0=")), None)
            if not namaste_file:
                return "error: no Namaste file (0=*) found"

            namaste_path = os.path.join(path, namaste_file)
            try:
                with open(namaste_path, "r", encoding="utf-8", errors="ignore") as fh:
                    content = fh.read()
            except OSError as exc:
                return f"error: cannot read Namaste file '{namaste_path}': {exc}"

            # Very naive heuristic: if the file mentions 'root' or 'storage',
            # we treat it as the root. If it mentions 'objectId' or 'content',
            # we treat it as an object. This can be extended as needed.
            lower = content.lower()
            if "root" in lower or "storage" in lower:
                return "root"
            if "objectid" in lower or "content" in lower:
                return "object"
            return "error: unrecognized Namaste content"

        return "error: path is neither file nor directory"
    except Exception as exc:
        return f"error: unexpected exception: {exc}"

