def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    if not isinstance(nodes, list):
        raise TypeError(f"Expected a list of tuples, got {type(nodes).__name__}")

    try:
        from ruamel.yaml.nodes import MappingNode
    except Exception:
        MappingNode = None

    def _merge_mapping(existing_map, new_map):
        """Merge new_map into existing_map in place."""
        if MappingNode is None or not isinstance(existing_map, MappingNode) or not isinstance(new_map, MappingNode):
            # Not mapping nodes; nothing to merge
            return existing_map

        # Build index of existing key nodes by value
        existing_index = {k_node.value: (k_node, v_node) for k_node, v_node in existing_map.value}

        for new_k, new_v in new_map.value:
            key_val = new_k.value
            if key_val in existing_index:
                existing_k, existing_v = existing_index[key_val]
                # If both values are mappings, merge recursively
                if isinstance(existing_v, MappingNode) and isinstance(new_v, MappingNode):
                    _merge_mapping(existing_v, new_v)
                    # keep existing key node
                else:
                    # Replace existing value with new value
                    existing_index[key_val] = (existing_k, new_v)
            else:
                # Append new key-value pair
                existing_map.value.append((new_k, new_v))
                existing_index[key_val] = (new_k, new_v)
        return existing_map

    merged = {}
    order = []

    for item in nodes:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError(f"Each item must be a tuple of (ScalarNode, value), got {item!r}")
        key_node, val_node = item
        try:
            key = key_node.value
        except Exception as e:
            raise ValueError(f"Key node does not provide a 'value' attribute: {key_node!r}") from e

        if key not in merged:
            merged[key] = (key_node, val_node)
            order.append(key)
        else:
            existing_key_node, existing_val_node = merged[key]
            # Determine merge strategy
            if MappingNode and isinstance(existing_val_node, MappingNode) and isinstance(val_node, MappingNode):
                # Deep merge mappings in place
                _merge_mapping(existing_val_node, val_node)
                merged[key] = (existing_key_node, existing_val_node)
            else:
                # Overwrite with new value (last wins)
                merged[key] = (existing_key_node, val_node)

    # Construct result list preserving first occurrence order
    result = [(merged[k][0], merged[k][1]) for k in order]
    return result

