def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not isinstance(size, str):
        raise TypeError("Size must be a string")
    size = size.strip()
    if not size:
        raise ValueError("Size string is empty")
    # Normalize to upper case for suffix comparison
    upper = size.upper()

    # Find where the numeric part ends
    numeric_part = ""
    suffix_part = ""
    for idx, ch in enumerate(upper):
        if ch.isdigit() or ch == ".":
            numeric_part += ch
        else:
            suffix_part = upper[idx:].strip()
            break
    if not numeric_part:
        raise ValueError(f"Invalid size string: {size}")

    try:
        number = float(numeric_part)
    except ValueError as exc:
        raise ValueError(f"Could not parse numeric value in size string: {size}") from exc

    # Default multiplier (bytes)
    multiplier = 1

    # Map first letter of suffix to multiplier (10^3)
    if suffix_part:
        # Handle common suffixes: K, M, G, T, P, E
        first = suffix_part[0]
        if first == "K":
            multiplier = 10**3
        elif first == "M":
            multiplier = 10**6
        elif first == "G":
            multiplier = 10**9
        elif first == "T":
            multiplier = 10**12
        elif first == "P":
            multiplier = 10**15
        elif first == "E":
            multiplier = 10**18
        else:
            raise ValueError(f"Unknown size suffix '{suffix_part}' in size string: {size}")

    return int(round(number * multiplier))

