def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not isinstance(url, str):
        raise TypeError(f"Expected url to be a str, got {type(url).__name__}")

    if not url_args:
        return url

    import re

    # Find placeholders enclosed in curly braces, e.g., {id}, {name}
    pattern = re.compile(r'\{([^{}]+)\}')

    def _substitute(match):
        key = match.group(1)
        if key not in url_args:
            raise KeyError(f"URL placeholder '{key}' not found in arguments")
        return str(url_args[key])

    try:
        return pattern.sub(_substitute, url)
    except re.error as exc:
        # In case of regex compilation errors or other re issues
        raise ValueError(f"Error processing URL template: {exc}") from exc

