    if not url_args:
        return url

    # Determine the type of url_args
    if isinstance(url_args, dict):
        args = url_args
    elif isinstance(url_args, (list, tuple)):
        # Use index-based placeholders like {0}, {1}, ...
        args = {str(idx): val for idx, val in enumerate(url_args)}
    else:
        raise TypeError(f"url_args must be a dict, list, or tuple, got {type(url_args).__name__}")

    # Replace placeholders of the form {key} with corresponding values
    def _replace(match):
        key = match.group(1)
        val = args.get(key)
        if val is None:
            # Leave the placeholder unchanged if key not found
            return match.group(0)
        # Ensure the value is string; do not URL‑encode here as callers may handle that
        return str(val)

    try:
        import re
    except ImportError:
        # Fallback: simple string replacement without regex
        for key, val in args.items():
            placeholder = f"{{{key}}}"
            if placeholder in url:
                url = url.replace(placeholder, str(val))
        return url

    pattern = re.compile(r"\{(\w+)\}")
    return pattern.sub(_replace, url)

