    import re
    placeholder_pattern = re.compile(r'\{([^{}]+)\}')
    placeholders = placeholder_pattern.findall(url)

    # Ensure all placeholders have corresponding arguments
    missing = [p for p in placeholders if p not in url_args]
    if missing:
        raise ValueError(
            f"Missing URL argument(s) for placeholder(s): {', '.join(missing)}"
        )

    # Replace placeholders with provided values
    new_url = url
    for ph in placeholders:
        value = url_args[ph]
        new_url = new_url.replace("{" + ph + "}", str(value))

    return new_url

