def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """

    # Basic input validation
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("only non‑negative integers are supported")
    if not (isinstance(alphabet, list) and all(isinstance(ch, str) for ch in alphabet)):
        raise TypeError("alphabet must be a list of strings")
    if not alphabet:
        raise ValueError("alphabet cannot be empty")
    if not all(len(ch) == 1 for ch in alphabet):
        raise ValueError("each alphabet entry must be a single character string")

    base = len(alphabet)

    # Convert the number to the target base
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        result = ''.join(reversed(digits))

    # Apply optional padding with the first alphabet character (typically '0')
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non‑negative")
        if len(result) < padding:
            pad_len = padding - len(result)
            result = alphabet[0] * pad_len + result

    return result

