def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    # Basic type validation
    if not isinstance(flow_params, dict):
        raise TypeError("'flow_params' must be a dict, got {!r}".format(type(flow_params)))
    if not isinstance(register_value, str):
        raise TypeError("'register_value' must be a str key, got {!r}".format(type(register_value)))

    # Allow register_number to be any value; we don't enforce numeric type
    def _traverse_and_replace(obj):
        if isinstance(obj, dict):
            keys_to_replace = [k for k in obj if k == register_value]
            for k in keys_to_replace:
                obj[k] = register_number
            # Recurse into values in case of nested structures
            for v in obj.values():
                _traverse_and_replace(v)
        elif isinstance(obj, list):
            for item in obj:
