def string_to_int(string: str, alphabet: List[str]) -> int:
    """Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two distinct characters.")
    # Build a fast lookup table for digit value
    try:
        digit_map = {ch: i for i, ch in enumerate(alphabet)}
    except TypeError as exc:
        raise TypeError("Alphabet must be a sequence of characters") from exc

    if not string:
        # Empty string is interpreted as zero
        return 0

    result = 0
    for ch in string:
        if ch not in digit_map:
            raise ValueError(f"Character {ch!r} not found in alphabet.")
        result = result * base + digit_map[ch]
    return result

