    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    import tarfile

    # Ensure the destination directory exists
    try:
        destination_path.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        raise OSError(f"Failed to create destination directory {destination_path!s}: {exc}") from exc

    # Derive the archive filename from the URL
    archive_name = url.split('/')[-1]
    if not archive_name:
        raise ValueError("URL does not contain a valid filename at the end.")
    archive_path = destination_path / archive_name

    # Download the archive
    try:
        with requests.get(url, stream=True, timeout=30) as resp:
            resp.raise_for_status()
            with open(archive_path, 'wb') as f:
                for chunk in resp.iter_content(chunk_size=8192):
                    if chunk:  # filter out keep-alive chunks
                        f.write(chunk)
    except requests.RequestException as exc:
        # Cleanup partially downloaded file
        if archive_path.exists():
            archive_path.unlink()
        raise ConnectionError(f"Failed to download archive from {url!s}: {exc}") from exc

    # Extract the archive
    try:
        with tarfile.open(archive_path, mode='r:gz') as tar:
            tar.extractall(path=destination_path)
    except tarfile.TarError as exc:
        # Cleanup the downloaded file and extracted contents
        if archive_path.exists():
            archive_path.unlink()
        # Remove any files that were extracted before the error
        for root, dirs, files in os.walk(destination_path, topdown=False):
            for name in files:
                try:
                    os.remove(os.path.join(root, name))
                except Exception:
                    pass
            for name in dirs:
                try:
                    os.rmdir(os.path.join(root, name))
                except Exception:
                    pass
        raise RuntimeError(f"Failed to extract archive {archive_path!s}: {exc}") from exc
    finally:
        # Optionally remove the archive file after extraction
        if archive_path.exists():
            try:
                archive_path.unlink()
            except Exception:
                pass

    return destination_path

