    """
    Checks if the operating system is macOS.

    :return: True if macOS
    :rtype: bool
    """
    # Prefer os.uname() on POSIX systems
    try:
        return getattr(os.uname(), 'sysname', '').lower() == 'darwin'
    except AttributeError:
        # Fallback: use environment variable OSTYPE if available
        ostype = os.getenv('OSTYPE', '').lower()
        if 'darwin' in ostype:
            return True
        # As a last resort, check sys.platform via os module if present
        # (Python's os module can expose platform info via os. name)
        if os.name == 'posix':
            try:
