def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = 'windows' if os.name == 'nt' else 'posix'
    elif platform in (1, '1'):
        platform = 'posix'
    elif platform in (0, '0'):
        platform = 'windows'
    else:
        raise ValueError(f"Unsupported platform value: {platform!r}")

    args = []
    buf = []
    in_quote = False
    quote_char = None

    i = 0
    L = len(s)
    while i < L:
        c = s[i]

        if not in_quote:
            if c.isspace():
                if buf:
                    args.append(''.join(buf))
                    buf.clear()
                i += 1
                continue
            if c in ('"', "'"):
                in_quote = True
                quote_char = c
                i += 1
                continue
            if platform == 'windows' and c == '\\':
                i += 1
                if i < L:
                    buf.append(s[i])
                    i += 1
                else:
