def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import pathlib
    from pathlib import Path

    # Resolve the temporary path
    tmp_base = Path(tmp_path)
    if not tmp_base.is_absolute():
        tmp_base = tmp_base.resolve()

    # Determine the target repository directory name
    if filename:
        repo_dir_name = filename
    else:
        repo_dir_name = Path(archive_path).stem

    repo_dir = tmp_base / repo_dir_name
    # Ensure uniqueness
    counter = 1
    base_dir = repo_dir
    while repo_dir.exists():
        repo_dir = base_dir.with_name(f"{base_dir.name}_{counter}")
        counter += 1

    repo_dir.mkdir(parents=True, exist_ok=True)

    ext = Path(archive_path).suffix.lower()
    cmd = None
    if ext in {".gz", ".tgz"} or Path(archive_path).suffix.lower() in {".tar"}:
        # tar.gz or .tar
        cmd = ["tar", "-xf", archive_path, "-C", str(repo_dir)]
    elif ext == ".zip":
        cmd = ["unzip", "-o", archive_path, "-d", str(repo_dir)]
    else:
        # try tar for tar.gz even if suffix isn't .tar.gz
        if archive_path.endswith(".tar.gz"):
            cmd = ["tar", "-xf", archive_path, "-C", str(repo_dir)]
        else:
            raise ValueError(f"Unsupported archive format for {archive_path}")

    try:
        subprocess.run(cmd, check=True)
    except subprocess.SubprocessError as e:
        raise RuntimeError(f"Failed to extract archive {archive_path}") from e

    return repo_dir.as_uri()

