    # Quick string checks
    if host_str in ("localhost", "127.0.0.1", "::1"):
        return True
    try:
        for res in socket.getaddrinfo(host_str, None):
            family, _, _, _, sockaddr = res
            if family in (socket.AF_INET, socket.AF_INET6):
                ip = sockaddr[0]
                # IPv6 loopback
                if ip == "::1":
