def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # In Git Bash, os.name will be 'posix' but OSTYPE contains 'msys' or 'cygwin'
        if os.name != 'posix':
            return False
        ostype = os.environ.get('OSTYPE', '').lower()
        if 'msys' in ostype or 'cygwin' in ostype:
            return True
        # Some environments use MSYSTEM for MSYS2
        msystem = os.environ.get('MSYSTEM', '').upper()
        if 'MINGW' in msystem or 'MSYS' in msystem:
            return True
        return False
    except Exception:
        # If anything goes wrong, assume not a Git Bash environment
        return False

