def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    # Basic validation
    if graph is None:
        raise ValueError("The 'graph' argument must not be None.")
    if prop is None:
        raise ValueError("The 'prop' argument must not be None.")
    if not hasattr(graph, "triples"):
        raise TypeError("The provided graph object does not support 'triples' method.")
    # Initialise collection of roots
    if roots is None:
        roots = set()
    else:
        # Ensure it's a set to allow add operations
        roots = set(roots)
    try:
        # Gather children and parents
        children = set()
        parents = set()
        for child, p, parent in graph.triples((None, prop, None)):
            # Only consider triples that actually have the specified property
            if p != prop:
                continue
            if child is None:
                continue
            children.add(child)
            if parent is not None:
                parents.add(parent)
        # Children that never appear as parents are roots
        for node in children:
            if node not in parents:
                roots.add(node)
    except Exception as exc:
        raise RuntimeError(f"Failed to process graph for roots extraction: {exc}") from exc
    return roots

