def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, os, re
    configs = {}
    error_records = []

    def _resolve_env_in_str(s):
        # Replace ${VAR} with environment variable value
        pattern = re.compile(r'\$\{([A-Za-z0-9_]+)\}')
        def repl(match):
            return os.getenv(match.group(1), match.group(0))
        return pattern.sub(repl, s)

    def _resolve_env_in_obj(obj):
        if isinstance(obj, dict):
            return {k: _resolve_env_in_obj(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_resolve_env_in_obj(v) for v in obj]
        elif isinstance(obj, str):
            return _resolve_env_in_str(obj)
        else:
            return obj

    for fn in config_filenames:
        try:
            with open(fn, 'r', encoding='utf-8') as fh:
                try:
                    cfg = json.load(fh)
                except ValueError as exc:
                    msg = f"Error parsing JSON in file '{fn}': {exc}"
                    record = logging.makeLogRecord({
                        'name': 'load_configurations',
                        'level': logging.ERROR,
                        'pathname': fn,
                        'lineno': 0,
                        'msg': msg,
                        'args': None,
                        'exc_info': exc,
                    })
                    error_records.append(record)
                    continue
                except Exception as exc:
                    msg = f"Unexpected error reading file '{fn}': {exc}"
                    record = logging.makeLogRecord({
                        'name': 'load_configurations',
                        'level': logging.ERROR,
                        'pathname': fn,
                        'lineno': 0,
                        'msg': msg,
                        'args': None,
                        'exc_info': exc,
                    })
                    error_records.append(record)
                    continue

                if resolve_env:
                    cfg = _resolve_env_in_obj(cfg)

                if overrides:
                    # shallow merge: top-level keys from overrides replace cfg keys
                    merged = cfg.copy()
                    merged.update(overrides)
                    cfg = merged

                configs[fn] = cfg
        except FileNotFoundError as exc:
            msg = f"Configuration file not found: '{fn}'"
            record = logging.makeLogRecord({
                'name': 'load_configurations',
                'level': logging.ERROR,
                'pathname': fn,
                'lineno': 0,
                'msg': msg,
                'args': None,
                'exc_info': exc,
            })
            error_records.append(record)
        except Exception as exc:
            msg = f"Unexpected error opening file '{fn}': {exc}"
            record = logging.makeLogRecord({
                'name': 'load_configurations',
                'level': logging.ERROR,
                'pathname': fn,
                'lineno': 0,
                'msg': msg,
                'args': None,
                'exc_info': exc,
            })
            error_records.append(record)

    return (configs, error_records)

