        try:
            with open(path, 'r', encoding='utf-8') as f:
                content = f.read()
            if ext in ('.yaml', '.yml'):
                try:
                    import yaml
                except Exception:
                    raise ImportError(f"PyYAML is required to parse YAML files: {path}")
                try:
                    return yaml.safe_load(content)
                except Exception as exc:
                    raise ValueError(f"YAML parsing error in {path}: {exc}")
