            raise FileNotFoundError(f"File not found: {path}") from exc

    # Helper to resolve environment variables in a dict
    env_pattern = re.compile(r'\$\{(?P<var>[A-Za-z0-9_]+)\}')

    def _resolve_env_in_obj(obj):
