            if filename in overrides and isinstance(overrides[filename], dict):
                if not isinstance(conf, dict):
                    raise ValueError(f"Override applies to a dict, but config for {filename} is not a dict")
                conf.update(overrides[filename])
            # Resolve environment variables
            if resolve_env:
                conf = _resolve_env_in_obj(conf)
            config_map[filename] = conf
        except Exception as exc:
            # Create a LogRecord for the error
            record = logging.LogRecord('config_loader', logging.ERROR, filename, 0,
                                       f"Failed to load configuration from {filename}: {exc}",
                                       None, None)
