    def _merge_dicts(target, src):
        for key, val in src.items():
            if (
                key in target
                and isinstance(target[key], dict)
                and isinstance(val, dict)
            ):
                _merge_dicts(target[key], val)
            else:
                target[key] = val

    # Helper to resolve environment variables in strings
    def _resolve_env(data):
        import os
        import re

        pattern = re.compile(r"\$\{([^}]+)\}")

        def _substitute(value):
            return pattern.sub(lambda m: os.getenv(m.group(1), m.group(0)), value)

        if isinstance(data, dict):
            return {_resolve_env(k): _resolve_env(v) for k, v in data.items()}
        elif isinstance(data, list):
            return [_resolve_env(i) for i in data]
        elif isinstance(data, str):
            return _substitute(data)
        else:
            return data

    logger_name = __name__
    for filename in config_filenames:
        try:
            # Determine the file format based on extension
            ext = filename.split(".")[-1].lower()
            with open(filename, "r", encoding="utf-8") as f:
                if ext in ("json", "jsn"):
                    import json

                    parsed = json.load(f)
                elif ext in ("yaml", "yml"):
                    try:
                        import yaml

                        parsed = yaml.safe_load(f)
                    except Exception as exc_yaml:
                        # If yaml is not available or fails, try json
                        raise exc_yaml
                elif ext in ("ini", "cfg"):
                    import configparser

                    parser = configparser.ConfigParser()
                    parser.read_file(f)
                    parsed = {s: dict(parser.items(s)) for s in parser.sections()}
                else:
                    # Unsupported extension; raise error to be caught below
                    raise ValueError(f"Unsupported file extension: {ext}")

            # Apply overrides if provided
            if overrides and isinstance(parsed, dict):
                _merge_dicts(parsed, overrides)

            # Resolve environment variables if requested
            if resolve_env:
                parsed = _resolve_env(parsed)

            config_map[filename] = parsed

        except Exception as exc:
            # Create a LogRecord for the error
            record = logging.LogRecord(
                name=logger_name,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"Failed to parse configuration file {filename}: {exc}",
                args=None,
                exc_info=True,
            )
            error_records.append(record)

    return config_map, error_records

