                var_name = match.group(1)
                return os.getenv(var_name, '')
            return re.sub(r'\$\{([^}]+)\}', _repl, obj)
        else:
            return obj

    configs = {}
    error_records = []

    # Ensure we iterate over a list-like collection
    filenames = list(config_filenames) if hasattr(config_filenames, '__iter__') else [config_filenames]

    for fname in filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                config_data = json.load(f)
        except Exception as exc:
            record = logging.LogRecord(name='load_configurations',
                                       level=logging.ERROR,
                                       pathname=fname,
                                       lineno=0,
                                       msg=f'Error parsing configuration file {fname}: {exc}',
                                       args=(),
                                       exc_info=None)
            error_records.append(record)
            continue

        if resolve_env:
            try:
                config_data = _resolve_env_vars(config_data)
            except Exception as exc:
                record = logging.LogRecord(name='load_configurations',
                                           level=logging.ERROR,
                                           pathname=fname,
                                           lineno=0,
                                           msg=f'Error resolving environment variables in {fname}: {exc}',
                                           args=(),
                                           exc_info=None)
                error_records.append(record)
                continue

        # Apply overrides if provided
        if overrides:
            if isinstance(overrides, dict):
                # Per-file overrides
                if fname in overrides and isinstance(overrides[fname], dict):
                    config_data.update(overrides[fname])
                else:
                    # Global overrides for all files
                    for key, val in overrides.items():
                        if key not in configs and isinstance(config_data, dict):
                            config_data[key] = val

