def scale(self, other=None, recompute=False):
        """Compute or set scale (integral of the histogram).

        If *other* is ``None``, return scale of this histogram.
        If its scale was not computed before,
        it is computed and stored for subsequent use
        (unless explicitly asked to *recompute*).
        Note that after changing (filling) the histogram
        one must explicitly recompute the scale
        if it was computed before.

        If a float *other* is provided, rescale self to *other*.

        Histograms with scale equal to zero can't be rescaled.
        :exc:`.LenaValueError` is raised if one tries to do that.
        """
        # Validate ``other`` if provided
        if other is not None and not isinstance(other, (int, float)):
            raise TypeError("other must be a float or int providing the new scale")

        # Helper to fetch current values
        def _get_values():
            for attr in ("values", "counts", "data", "bins"):
                if hasattr(self, attr):
                    return getattr(self, attr)
            # Try iteration over self (dict-like)
            try:
                return self
            except Exception:
                raise AttributeError("object does not expose histogram values")

        # Compute current scale
        def _compute_scale():
            vals = _get_values()
            try:
                if isinstance(vals, dict):
                    return float(sum(vals.values()))
                # iterable of numbers
                return float(sum(vals))
            except Exception as e:
                raise RuntimeError(f"cannot sum histogram values: {e}")

        # 1. Return existing scale if possible
        if other is None:
            # If already computed and not forced to recompute
            current_scale = getattr(self, "_scale", None)
            if current_scale is not None and not recompute:
                return current_scale
            # Compute and store
