def scale(self, other=None):
        """Get or set the scale of the graph.

        If *other* is ``None``, return the scale of this graph.

        If a numeric *other* is provided, rescale to that value.
        If the graph has unknown or zero scale,
        rescaling that will raise :exc:`~.LenaValueError`.

        To get meaningful results, graph's fields are used.
        Only the last coordinate is rescaled.
        For example, if the graph has *x* and *y* coordinates,
        then *y* will be rescaled, and for a 3-dimensional graph
        *z* will be rescaled.
        All errors are rescaled together with their coordinate.
        """
        # Retrieve the current scale
        current_scale = getattr(self, "_scale", None)

        # If no argument provided, simply return the current scale
        if other is None:
            return current_scale

        # Validate that the current scale is set and non-zero
        if current_scale is None or current_scale == 0:
            raise LenaValueError(
                "Cannot rescale because the current scale is unknown or zero."
            )

        # Ensure the new scale is a number
        if not isinstance(other, (int, float)):
            raise TypeError(f"Expected a numeric value for new scale, got {type(other).__name__}")

        if other == 0:
            raise ValueError("New scale must not be zero.")

        # Compute the scaling factor: new_value = old_value * (new / old)
        factor = other / current_scale

        # Set the new scale
        self._scale = other

        # Helper function to scale a list of numeric values in place
        def _scale_list(lst):
            for i, v in enumerate(lst):
                try:
                    lst[i] = v * factor
                except TypeError:
                    pass  # ignore non-numeric entries

        # Attempt to scale the graph's data points
        if hasattr(self, "values") and isinstance(self.values, dict):
            # Assume keys are field names, last key is the last coordinate
            try:
                last_field = list(self.values.keys())[-1]
                _scale_list(self.values[last_field])
            except (IndexError, ValueError):
                pass  # no fields to scale
            # Scale associated errors if present
            if hasattr(self, "errors") and isinstance(self.errors, dict):
                try:
                    err_field = list(self.errors.keys())[-1]
                    _scale_list(self.errors[err_field])
                except (IndexError, ValueError):
                    pass
        elif hasattr(self, "data") and isinstance(self.data, list):
            for point in self.data:
