def verifyObject(iface, candidate, tentative=False):
    """Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.

    """
    errors = []

    # 1. Check if candidate declares that it provides the interface
    if not tentative:
        try:
            provides = iface.providedBy(candidate)
        except Exception as e:
            errors.append(f"Error checking providedBy for {candidate}: {e}")
        else:
            if not provides:
                errors.append(f"{candidate!r} does not explicitly provide interface {iface.__name__}")

    # 2. Check required attributes
    try:
        required_attrs = iface.getRequiredAttributes()
    except Exception:
        required_attrs = []
    for attr in required_attrs:
        if not hasattr(candidate, attr):
            errors.append(f"Missing required attribute '{attr}' on {candidate!r}")

    # 3. Check required methods
    try:
        required_methods = iface.getRequiredMethods()
    except Exception:
        required_methods = []
    for name in required_methods:
        if not hasattr(candidate, name):
            errors.append(f"Missing required method '{name}' on {candidate!r}")
        else:
            # optional: try to compare signatures if both are callable
            func = getattr(candidate, name)
            if callable(func):
                # attempt to get interface method signature if available
                try:
                    iface_method = getattr(iface, name)
                    # Using inspect.signature would be ideal, but importing is disallowed.
                    # As a lightweight check, we compare the __code__.co_varnames length
                    # for functions defined in Python (this is a very approximate check).
                    # This block is intentionally simple to respect the no-import rule.
                    if hasattr(iface_method, "__code__") and hasattr(func, "__code__"):
                        iface_args = iface_method.__code__.co_varnames[:iface_method.__code__.co_argcount]
                        cand_args = func.__code__.co_varnames[:func.__code__.co_argcount]
                        if iface_args != cand_args:
                            errors.append(f"Method '{name}' signature mismatch on {candidate!r}")
                except Exception:
                    pass

    # 4. Raise collected errors or return True
    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("; ".join(errors))
    return True

