def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Basic validation of inputs
    if iface is None or candidate is None:
        raise ValueError("iface and candidate must not be None")

    # If iface is a type (e.g., a class or ABC), use isinstance/issubclass checks
    if isinstance(iface, type):
        if isinstance(candidate, type):
            ok = issubclass(candidate, iface)
        else:
            ok = isinstance(candidate, iface)
        if not ok:
            msg = f"Candidate {candidate!r} does not provide interface {iface.__name__}"
            if tentative:
                return False
            raise TypeError(msg)
        return True

    # Fallback: treat iface as an object with attributes that must be present on candidate
    missing = []
    for name in dir(iface):
        if name.startswith("_"):
            continue  # ignore private/internal attributes
        if not hasattr(candidate, name):
            missing.append(name)

    if missing:
        iface_name = getattr(iface, "__name__", repr(iface))
        msg = f"Candidate {candidate!r} is missing attributes required by interface {iface_name}: {', '.join(missing)}"
        if tentative:
            return False
        raise AttributeError(msg)

    return True

