    """Verify that the *candidate* might correctly provide *iface*."""
    # Basic validation of inputs
    if iface is None:
        raise ValueError("iface must be provided")
    if candidate is None:
        return False

    # Resolve the class of the candidate (instance or class)
    if isinstance(candidate, type):
        cand_cls = candidate
    else:
        cand_cls = candidate.__class__

    # First, a quick isinstance/issubclass check (covers standard inheritance)
    try:
        if issubclass(cand_cls, iface):
            return True
    except TypeError:
        # cand_cls is not a class or iface is not a class; skip
        pass

    # Import inspect locally to avoid module-level imports
    import inspect

    # Gather callable members defined on the interface (methods and functions)
    iface_members = {
        name
        for name, member in inspect.getmembers(iface)
        if inspect.isroutine(member) or inspect.isbuiltin(member)
    }

    # Collect any required members that the candidate does not have
    missing = []
    for name in iface_members:
        if not hasattr(cand_cls, name) and not hasattr(candidate, name):
            missing.append(name)

    if missing:
        if tentative:
            return False
        raise ValueError(
