def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Helper to find most derived metaclass that is a subclass of both
    def _common_metaclass(m1, m2):
        if m1 is None:
            return m2
        if m2 is None:
            return m1
        # Prefer the more derived metaclass
        if issubclass(m1, m2):
            return m1
        if issubclass(m2, m1):
            return m2
        raise TypeError(f"metaclass conflict: {m1.__name__!r} vs {m2.__name__!r}")

    # If an explicit metaclass is supplied, use it
    if explicit_mc is not None:
        return explicit_mc

    if not bases:
        # No bases – fall back to the default metaclass
        return type

    # Start with the metaclass of the first base
    metaclass = type(bases[0])
    # Merge with each subsequent base's metaclass
    for base in bases[1:]:
        metaclass = _common_metaclass(metaclass, type(base))

    return metaclass

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Ensure bases is an iterable with at least one element.
    if isinstance(bases, type):
        # single base
        bases = (bases,)
    elif not isinstance(bases, (tuple, list)):
        raise TypeError("bases must be a class or a tuple/list of classes")

    if not bases:
        raise TypeError("determineMetaclass() needs at least one base class")

    # Gather metaclasses from each base.
    metaclasses = []
    for base in bases:
        if not isinstance(base, type):
            raise TypeError(f"Base {base!r} is not a class (type)")
        metaclasses.append(type(base))

    # If an explicit metaclass was supplied, validate it.
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit_mc must be a class (metaclass)")
        # The explicit metaclass must be a subclass of each base's metaclass.
        for mc in metaclasses:
            if not issubclass(explicit_mc, mc):
                raise TypeError(
                    f"explicit_mc {explicit_mc.__name__} is not a subclass "
                    f"of base's metaclass {mc.__name__}"
                )
        return explicit_mc

    # Resolve the most derived metaclass (the one that is a subclass of all others).
    result = metaclasses[0]
    for mc in metaclasses[1:]:
        if issubclass(mc, result):
            result = mc
        elif issubclass(result, mc):
            # current result is more derived – keep it
            continue
        else:
            # Conflicting metaclasses cannot coexist.
            raise TypeError(
                f"Conflicting metaclasses {result.__name__!r} and {mc.__name__!r}"
            )

    return result

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If the caller explicitly provided a metaclass, honour it.
    if explicit_mc is not None:
        return explicit_mc

    # Find the most derived metaclass that is a superclass of all base metaclasses.
    metaclass = None
    for base in bases:
        # In Python 3 the metaclass of a class is its type; in Python 2 it could be
        # stored in the __metaclass__ attribute of the base.
        candidate = getattr(base, "__metaclass__", None) or type(base)

        if metaclass is None:
            metaclass = candidate
