        """Remove and return the `(key, value)` pair least frequently used."""
        # Ensure the container is not empty
        if not self:
            raise KeyError('dictionary is empty')

        # Determine the key to remove
        try:
            # Prefer a dedicated frequency map if one exists
            freq_map = getattr(self, 'freq', None)
            if isinstance(freq_map, dict):
                # Pick the key with the smallest frequency
                min_key = min(freq_map, key=freq_map.get)
            else:
                # Fall back to the first key in the container
                min_key = next(iter(self))
        except Exception:
            min_key = next(iter(self))

        # Remove the key/value from the main container
        value = self.pop(min_key)

        # Remove the key from any frequency tracking structure
        if hasattr(self, 'freq'):
            try:
                del self.freq[min_key]
            except KeyError:
                pass

        return (min_key, value)

