    # named `data`, where each value is a tuple `(value, frequency)`.
    # If the container is empty, a `KeyError` is raised.
    if not hasattr(self, 'data') or not isinstance(self.data, dict):
        raise TypeError(
            "popitem() requires an attribute `data` that is a dictionary "
            "mapping keys to (value, frequency) tuples."
        )
    if not self.data:
        raise KeyError("popitem() called on an empty container")
    try:
        # Find the key with the lowest usage frequency
        min_key = min(
