            key=lambda kv: kv[1][1]
        )[0]
    except (IndexError, ValueError, TypeError, AttributeError):
        # Fallback: assume the stored value itself is the frequency
        min_key = min(
            self.data.items(),
            key=lambda kv: getattr(kv[1], 'freq', 0)
        )[0]
    value, _ = self.data.pop(min_key)
    return (min_key, value)

