def _create_in_regex(self) -> Pattern:
    """Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    # The in‑style parameters are typically expressed as `in:<value>` or `in=<value>`.
    # This regex captures the value part and is case‑insensitive.
    # It optionally allows a colon or an equals sign between ``in`` and the value.
    # The captured value stops at whitespace or a semicolon, which is common in
    # attribute lists.
    try:
        pattern = r'(?i)\bin[ :]?([^\s;]+)'
        return re.compile(pattern)
    except re.error:
        # In the unlikely event the regex cannot compile, fall back to a very
        # permissive pattern that simply matches the literal string "in".
        return re.compile(r'in', re.IGNORECASE)

