def fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    if dt is None:
        raise ValueError("dt argument must not be None")
    if not hasattr(dt, "tzinfo") or dt.tzinfo is None:
        raise ValueError("dt must be timezone-aware")

    # Convert the datetime to the target timezone.
    try:
        target = dt.astimezone(self.tz)
    except Exception as exc:
        raise ValueError(f"Failed to convert datetime to target timezone: {exc}") from exc

    # Determine if the original datetime is ambiguous.
    ambiguous = False
    fold_assigned = False
    if hasattr(self.tz, "is_ambiguous"):
        try:
            ambiguous = self.tz.is_ambiguous(dt)
        except Exception:
            ambiguous = False

    if ambiguous:
        # Preserve the fold state from the original datetime if present.
        fold = getattr(dt, "fold", 0)
        if fold:
            # Use replace to set fold on the resulting datetime.
            try:
                target = target.replace(fold=1)
                fold_assigned = True
            except TypeError:
                # Older Python versions (<3.7) do not support fold on replace
                pass

    # If fold was not reassigned but the original had fold set, copy it if possible.
    if not fold_assigned and hasattr(target, "replace"):
        fold = getattr(dt, "fold", 0)
        try:
            target = target.replace(fold=fold)
        except TypeError:
            pass

    return target

