def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation of URL
    if not isinstance(url, str) or not url:
        raise ValueError("The 'url' argument must be a non-empty string.")
    # Ensure the URL has http or https scheme
    if not (url.startswith("http://") or url.startswith("https://")):
        raise ValueError("URL must start with http:// or https://.")

    # Remove trailing slash from the base URL for consistency
    base_url = url.rstrip('/')

    # Build the document path
    if document_path is None:
        # Default path used by NodeInfo
        full_path = f"{base_url}/nodeinfo/2.0"
    else:
        # Ensure the custom document_path starts with a slash
        if not document_path.startswith("/"):
            document_path = "/" + document_path
        full_path = f"{base_url}{document_path}"

    # Return a minimal .well-known/nodeinfo document structure
    return {
        "links": [
            {
                "rel": "self",
                "href": full_path
            }
        ]
    }

