def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Import required libraries locally to avoid global imports
    try:
        from lxml import etree
        import xmlsec
    except Exception as exc:
        raise RuntimeError("XML signature verification requires the 'lxml' and 'xmlsec' packages.") from exc

    # Ensure the public key is a PEM encoded string
    if not isinstance(public_key, (bytes, str)):
        raise TypeError("public_key must be a bytes or str containing PEM encoded key")
    if isinstance(public_key, bytes):
        public_key_b64 = public_key
    else:
        public_key_b64 = public_key.encode()

    # Parse the document XML
    if isinstance(doc, str):
        try:
            doc_root = etree.fromstring(doc.encode())
        except Exception as exc:
            raise ValueError("Provided doc is not valid XML.") from exc
    elif isinstance(doc, etree._Element):
        doc_root = doc
    else:
        raise TypeError("doc must be a string or lxml.etree.Element")

    # Convert the signature into an element if it isn't already
    if isinstance(signature, str):
        try:
            sig_node = etree.fromstring(signature.encode())
        except Exception as exc:
            raise ValueError("Provided signature is not valid XML.") from exc
    elif isinstance(signature, etree._Element):
        sig_node = signature
    else:
        raise TypeError("signature must be a string or lxml.etree.Element")

    # Ensure the signature is part of the document
    if sig_node.getparent() is None:
        doc_root.append(sig_node)

    # Load the public key
    try:
        key = xmlsec.Key.from_memory(public_key_b64, xmlsec.KeyFormat.PEM, None)
    except Exception as exc:
        raise ValueError("Could not load public key.") from exc

    ctx = xmlsec.SignatureContext()
    ctx.key = key

