        The signature element (or the entire signed message).

    Returns
    -------
    bool
        ``True`` if the signature verifies, ``False`` otherwise.

    Raises
    ------
    ValueError
        If required arguments are missing or of the wrong type.
    RuntimeError
        If required XML security libraries (lxml, xmlsec) are not available.
    """
    try:
        from lxml import etree
        import xmlsec
    except Exception as exc:
        raise RuntimeError(
            "Required XML security libraries (lxml, xmlsec) are not available."
        ) from exc

    # ----- Validate input types --------------------------------------------------
    if public_key is None:
        raise ValueError("Public key must be provided")

    if doc is None:
        raise ValueError("Document must be provided")

    if signature is None:
        raise ValueError("Signature must be provided")

    # ----- Convert inputs to etree elements ---------------------------------------
    try:
        if isinstance(doc, (bytes, str)):
            doc = etree.fromstring(doc)
        elif not isinstance(doc, etree._Element):
            raise TypeError
    except Exception as exc:
        raise ValueError("Error parsing the XML document") from exc

    try:
        if isinstance(signature, (bytes, str)):
            signature = etree.fromstring(signature)
        elif not isinstance(signature, etree._Element):
            raise TypeError
    except Exception as exc:
        raise ValueError("Error parsing the signature element") from exc

    # ----- Prepare the public key --------------------------------------------------
    key_obj = None
    try:
        if isinstance(public_key, (bytes, str)):
            # Assume public_key is a PEM string or a path to a PEM file.
            if isinstance(public_key, bytes):
                key_data = public_key
            else:
                # Try to read from file; if fails, treat as PEM string
                try:
                    with open(public_key, "rb") as f:
                        key_data = f.read()
                except Exception:
                    key_data = public_key.encode("utf-8")
            key_obj = xmlsec.Key.from_memory(key_data, xmlsec.constants.KeyDataFormatPem, None)
        else:
            raise TypeError
    except Exception as exc:
        raise ValueError("Unable to load the public key") from exc

    # ----- Create verification context -------------------------------------------
    ctx = xmlsec.SignatureContext()
    ctx.key = key_obj

    # ----- Locate the signature node ---------------------------------------------
    # Try to find a <ds:Signature> element if it isn't provided directly.
    sig_node = xmlsec.tree.find_node(doc, xmlsec.constants.TransformSignature)
    if sig_node is None:
        sig_node = signature

    # ----- Perform verification ----------------------------------------------------
    try:
        ctx.verify(sig_node)
        return True
    except xmlsec.VerificationError:
        return False
    except Exception as exc:
        # Unexpected error
        raise RuntimeError("An unexpected error occurred during signature verification") from exc

