def get_silent_args(self, args):
    """Return a list of argument names that are considered 'silent'.

    An argument is treated as silent if its value is None or an empty string.
    This method accepts either a mapping (e.g. dict) or an iterable of
    ``(name, value)`` tuples, and it gracefully ignores unexpected input types.

    Parameters
    ----------
    args : Mapping or Iterable

        Either a dictionary of arguments or an iterable of (name, value) pairs.

    Returns
    -------
    list
        List of argument names that have silent values.
    """
    silent = []
    try:
        # Use a mapping interface if possible
        if isinstance(args, dict):
            iterable = args.items()
        # For sequences of tuples
        elif isinstance(args, (list, tuple)):
            iterable = args
        else:
            iterable = []
    except Exception:
        iterable = []

    for name, value in iterable:
        try:
            if value is None or value == "":
                silent.append(name)
        except Exception:
            continue

    return silent

