def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import os
    import subprocess
    import json

    # Validate playbook path
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    # Build base command
    cmd = ["ansible-playbook"]

    # Verbosity
    if verbose is not None:
        try:
            v = int(verbose)
            if v > 0:
                cmd.append("-" + "v" * v)
        except (ValueError, TypeError):
            # Preserve string flags like 'vvv'
            if isinstance(verbose, str):
                cmd.append(verbose)

    # Extra vars
    if extra_vars:
        try:
            ev_str = json.dumps(extra_vars, separators=(",", ":"))
        except (TypeError, ValueError):
            raise ValueError("extra_vars must be JSON serializable")
        cmd.append("--extra-vars")
        cmd.append(ev_str)

    # Additional ansible arguments
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, val in ansible_args.items():
            # Allow boolean flags
            if isinstance(val, bool):
                if val:
                    cmd.append(key)
            else:
                cmd.append(key)
                cmd.append(str(val))

    # Playbook file
    cmd.append(playbook_path)

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            cwd=ir_workspace.code_path if hasattr(ir_workspace, "code_path") else None,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=False,
        )
    except Exception as exc:
        err_msg = f"Failed to run ansible-playbook: {exc}"
        # Preferir plugin logging if available
        if hasattr(ir_plugin, "log"):
            ir_plugin.log.error(err_msg)
        else:
            print(err_msg, file=sys.stderr)
        raise

    # Log or print output based on verbosity
    if hasattr(ir_plugin, "log"):
        if result.stdout:
            ir_plugin.log.debug(result.stdout)
        if result.stderr:
            ir_plugin.log.error(result.stderr)
    else:
        if result.stdout:
            print(result.stdout)
        if result.stderr:
            print(result.stderr, file=sys.stderr)

    # Raise on non-zero exit code
    if result.returncode != 0:
        raise subprocess.CalledProcessError(
            result.returncode, cmd, output=result.stdout, stderr=result.stderr
        )

    return result.returncode

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level (int or None)
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import json

    # Build base command
    cmd = ['ansible-playbook', playbook_path]

    # Add verbosity flag if provided
    if verbose:
        try:
            lvl = int(verbose)
            if lvl > 0:
                cmd.append('-' + 'v' * lvl)
        except Exception:
            # ignore invalid verbosity values
            pass

    # Add extra_vars if provided
    if extra_vars:
        try:
            json_vars = json.dumps(extra_vars)
            cmd += ['--extra-vars', json_vars]
        except Exception:
            # Fallback to simple key=value string
            kv_pairs = ' '.join(f'{k}={v}' for k, v in extra_vars.items())
            cmd += ['--extra-vars', kv_pairs]

    # Add any other ansible arguments
    if ansible_args:
        for key, value in ansible_args.items():
            # Ensure key starts with '--'
            flag = key if key.startswith('--') else f'--{key}'
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
            elif isinstance(value, list):
                for v in value:
                    cmd.extend([flag, str(v)])
            elif value is not None:
                cmd.extend([flag, str(value)])

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False
        )
    except FileNotFoundError:
        raise RuntimeError("ansible-playbook command not found. Make sure Ansible "
                           "is installed and in your PATH.")
    except Exception as exc:
        raise RuntimeError(f"Failed to run ansible-playbook: {exc}")

    # Log output if plugin provides a logger
    if ir_plugin and hasattr(ir_plugin, 'logger'):
        ir_plugin.logger.debug("Ansible stdout: %s", result.stdout.strip())
        if result.stderr:
            ir_plugin.logger.warning("Ansible stderr: %s", result.stderr.strip())

    # Return a tuple of return code, stdout, stderr
    return result.returncode, result.stdout, result.stderr

