def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        def _convert_value(v):
            """Recursively convert a single value or collection of values."""
            # Handle None or already converted primitives
            if v is None or isinstance(v, (int, float, bool)):
                return v

            # Convert lists
            if isinstance(v, list):
                return [_convert_value(item) for item in v]

            # Convert dicts
            if isinstance(v, dict):
                return {k: _convert_value(val) for k, val in v.items()}

            # Now we are on a string
            if not isinstance(v, str):
                # If it's not a string but an unexpected type, leave it unchanged
                return v

            s = v.strip()
            if s == '':
                return None

            # Boolean conversion (case-insensitive)
            lowered = s.lower()
            if lowered in ('true', 'false'):
                return lowered == 'true'

            # Integer conversion
            try:
                if s.startswith('0x') or s.startswith('0X'):
                    return int(s, 16)
                if s.startswith('0o') or s.startswith('0O'):
                    return int(s, 8)
