    """
    Adds the spec cli options to to the main entry point.

    :param subparser: the subparser object to extend.
    """
    if root_subparsers is None:
        raise ValueError("root_subparsers cannot be None")
    if not hasattr(root_subparsers, "add_parser"):
        raise AttributeError(
            "root_subparsers must provide an add_parser method"
        )
    # Determine a sensible parser name and description
    parser_name = getattr(self, "name", self.__class__.__name__.lower())
    parser_desc = getattr(self, "description", None)
    try:
        parser = root_subparsers.add_parser(
            parser_name, description=parser_desc
        )
    except Exception as exc:
        raise RuntimeError(
            f"Failed to add parser '{parser_name}' to the CLI root subparsers"
        ) from exc
    # Add common CLI arguments. These can be overridden by subclasses.
    try:
        parser.add_argument(
            "--spec",
            type=str,
            help="Path to the spec file",
            required=False,
        )
        parser.add_argument(
            "--verbose",
            action="store_true",
            help="Enable verbose output",
        )
    except Exception:
        # If adding arguments fails we silently ignore; it will not break the CLI
        pass
    return parser

