def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os

    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("path and root must be strings")

    # Normalize to collapse redundant separators and resolve . and ..
    norm_path = os.path.normpath(path)
    norm_root = os.path.normpath(root)

    if not norm_root:
        raise ValueError("root cannot be empty")

    # If path and root are exactly the same, return empty string to signify
    # the root itself
    if norm_path == norm_root:
        return ''

    # Ensure we compare whole directory segments by appending a separator
    if not norm_root.endswith(os.sep):
        norm_root += os.sep

    if norm_path.startswith(norm_root):
        # Skip the root part and strip any leading separator in the remainder
        stripped = norm_path[len(norm_root):]
        return stripped.lstrip(os.sep)

    # If the root is not a prefix of the path, raise an informative error
    raise ValueError(f"Path '{path}' does not start with root '{root}'.")

